try bloğuna hata oluşturabilecek kodu koyarız, except bloğunda ise hatayı yakalarız. Örnek:

try:
    result = 10 / 0
except ZeroDivisionError as e:
    print("Hata oluştu:", e)

class MyError(Exception):
    def __init__(self, message):
        super().__init__(message)

# Kullanım:
raise MyError("Özel hata mesajı")

import logging
logging.basicConfig(filename='hata.log', level=logging.ERROR)
try:
    1/0
except Exception as e:
    logging.error("Hata: %s", e)
